import org.springframework.boot.test.web.server.LocalServerPort;
import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
import org.vaadin.addons.dramafinder.element.TextFieldElement;

/**
 * Drives the real, running application in a headless Chromium browser via Drama
 * Finder/Playwright. Complements {@link CustomerListViewTest}: what the address
 * bar says and how many requests typing costs can only be observed here.
 */
@SpringBootTest(classes = Application.class, webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port + "/";
    }

    @BeforeEach
    void clearLog() {
        queryLog.clear();
    }

    @Test
    void typingAndSelectingUpdateTheAddressBarWithoutEnter() {
        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
        nameFilter.setValue("vir");
        page.waitForTimeout(500);
        assertTrue(page.url().contains("name=vir"), "Expected URL to contain name=vir, was " + page.url());

        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
        statusFilter.selectItems("ACTIVE");
        page.waitForTimeout(500);
        assertTrue(page.url().contains("status=ACTIVE"),
                "Expected URL to contain status=ACTIVE, was " + page.url());

        nameFilter.setValue("");
        page.waitForTimeout(500);
        assertTrue(!page.url().contains("name="), "Clearing the name filter should drop it from the URL, was " + page.url());
    }

    @Test
    void typingANineLetterNameCostsAtMostTwoQueries() {
        Locator input = page.locator("vaadin-text-field input");
        input.pressSequentially("Aaltonen", new Locator.PressSequentiallyOptions().setDelay(50));
        page.waitForTimeout(600);

        assertTrue(queryLog.countQueries().size() <= 2,
                "Typing a nine-letter name should cost one or two backend queries, cost "
                        + queryLog.countQueries().size());
    }

    @Test
    void openingWithQueryParametersAppliesAndDisplaysTheFilter() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");
        page.waitForTimeout(500);

        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
        assertEquals("vir", nameFilter.getValue());

        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
        assertEquals(List.of("ACTIVE", "CLOSED"), statusFilter.getSelectedItems());
    }
}
